files.scripts/main.gd:
extends Node
## The base's shell (fixture): opens the rink core with the cartridge data/match.json names, steps it once a frame.

var ctx
var rink
var over := false


func _pack_setup(c) -> void:
	ctx = c
	var match_cfg: Dictionary = ctx.data.json("match.json")
	rink = ctx.cores.open("rink", String(match_cfg.get("cartridge", "game.cartridge.json")))
	rink.reset(ctx.seed)


func _pack_tick(_frame: int) -> void:
	over = not rink.step()


func _pack_state() -> Dictionary:
	return {"over": over, "rink": ctx.cores.state().get("rink", {})}

files.tests/bot_first_match.gd:
extends Node
## The player's first match (fixture): PLAY NOW, the same hand to the final whistle.

var ctx
var done := false


func _bot_setup(c) -> void:
	ctx = c


func _bot_tick(frame: int) -> void:
	done = frame >= 600


func _bot_done() -> bool:
	return done


func _bot_result() -> Dictionary:
	return {"ok": done, "summary": "first match to the whistle"}

