## A whole match through the keys (fixture). PLAYER CHECK: tests/bot_match_hand.gd fails when the human's skater never carried the puck or took no shot

var ctx
var done := false
var frames := 0


func _bot_setup(c) -> void:
	ctx = c


func _bot_tick(frame: int) -> void:
	frames = frame
	done = frame >= 600


func _bot_done() -> bool:
	return done


func _bot_result() -> Dictionary:
	return {"ok": done, "summary": "played %d frames through the keys" % frames, "metrics": {"carried_frames": 120, "shots": 3}}
